import{_ as o,l as i,o as e,c as l,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"DASH / HLS","description":"","frontmatter":{"title":"DASH / HLS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dash-hls.md","filePath":"cs/dash-hls.md","lastUpdated":1789023840000}'),T={name:"cs/dash-hls.md"};function c(S,a,A,_,E,D){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="dash-hls" tabindex="-1">DASH / HLS <a class="header-anchor" href="#dash-hls" aria-label="Permalink to &quot;DASH / HLS&quot;">​</a></h1><div class="epigraph"><p>把视频切成片段，用清单列出多码率 URL；播放器用 HTTP GET 拉片，中间是普通缓存，而不是一条永不结束的媒体 TCP。</p><footer>—— 据 ISO/IEC 23009 DASH；RFC 8216 HLS 整理</footer></div><p><a href="/cs/http">HTTP</a> 与 <a href="/cs/cdn-intuition">CDN</a> 已能缓存 GET。<a href="/cs/stun-turn">上一课</a> 是实时通话。缺口是<strong>点播/直播切片</strong>：MPD/m3u8、分片、与 WebRTC 对照。本课不把 ABR 算法写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTSP/RTP 难穿缓存与企业代理。DASH/HLS：编码多个 bitrate 的短文件（2–10 s），清单描述时间线。播放器按清单 GET，CDN 当静态对象。直播把清单滑窗。与 SSE：都是 HTTP，SSE 是事件，这里是媒体文件。H3 可拉片，0-RTT 适合幂等 GET。</p><p>不要把切片写成 MPEG 压缩课。</p><p><span class="marginnote">HLS RFC 8216。DASH 是 ISO。本课钉分发，不钉编码器。</span></p><h3 id="清单加-http-分片" tabindex="-1">清单加 HTTP 分片 <a class="header-anchor" href="#清单加-http-分片" aria-label="Permalink to &quot;清单加 HTTP 分片&quot;">​</a></h3><p>CDN 当静态对象缓存。直播滑窗。延迟由分片时长与缓冲决定，不是物理传播。Progressive 单文件失去 ABR。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：清单 → 选表示 → GET 分片。对照 WebRTC 推流。与巨帧无关直接；分片大小影响请求率和 ABR。</p>',11)),(e(),n(p,null,{default:r(()=>[h(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAN%5B%22%E6%B8%85%E5%8D%95%20MPD%2Fm3u8%22%5D%20--%3E%20BR%5B%22%E5%A4%9A%E7%A0%81%E7%8E%87%22%5D%0A%20%20BR%20--%3E%20GET%5B%22HTTP%20GET%20%E5%88%86%E7%89%87%22%5D%0A%20%20GET%20--%3E%20CDN%5B%22%E5%8F%AF%E7%BC%93%E5%AD%98%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GeoDNS 找近边缘。Cookie 可用于鉴权 URL。队头：H1 多连接拉片；H2 多流。PMTUD 影响分片下载。DRM 在分片上，点名。</p><p>直播延迟 ≈ 分片时长 × 缓冲片数，不是卫星那种物理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CMAF 的全部。ABR 自适应码率是下一课。后课默认：自适应流 = 清单 + HTTP 分片 + 缓存。</p><p>把整部电影当一个文件 Progressive Download 失去 ABR 与缓存粒度。</p><p>上一课留下的缺口在本课收口；「DASH / HLS」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/abr-streaming">ABR 自适应码率</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分片 + 清单，走标准 HTTP。</li><li>CDN 友好；直播滑窗清单。</li><li>延迟由分片和缓冲策略决定。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：ISO DASH；RFC 8216。</li></ul>',10))])}const H=o(T,[["render",c]]);export{u as __pageData,H as default};
